"""Delete-relaxation heuristics: h_max, h_add and the FF heuristic."""

from __future__ import annotations

import math
from collections import deque

from .base import Heuristic
from .relaxation import RelaxedTask, goal_value, propagate_costs


class HMaxHeuristic(Heuristic):
    """h_max: the most expensive relaxed goal fact. Admissible."""

    name = "hmax"
    admissible = True

    def __init__(self, task):
        super().__init__(task)
        self.rt = RelaxedTask(task)

    def __call__(self, state) -> float:
        cost, _ = propagate_costs(self.rt, state, additive=False)
        return goal_value(cost, self.rt.goal, additive=False)


class HAddHeuristic(Heuristic):
    """h_add: sum of relaxed goal-fact costs. Informative, not admissible."""

    name = "hadd"

    def __init__(self, task):
        super().__init__(task)
        self.rt = RelaxedTask(task)

    def __call__(self, state) -> float:
        cost, _ = propagate_costs(self.rt, state, additive=True)
        return goal_value(cost, self.rt.goal, additive=True)


class FFHeuristic(Heuristic):
    """FF heuristic: cost of a relaxed plan extracted from the h_add graph."""

    name = "hff"

    def __init__(self, task):
        super().__init__(task)
        self.rt = RelaxedTask(task)

    def __call__(self, state) -> float:
        cost, supporter = propagate_costs(self.rt, state, additive=True)
        if any(math.isinf(cost[g]) for g in self.rt.goal):
            return math.inf
        relaxed_plan: set = set()
        seen: set = set()
        queue = deque(self.rt.goal)
        while queue:
            fact = queue.popleft()
            if fact in state or fact in seen:
                continue
            seen.add(fact)
            op_idx = supporter[fact]
            if op_idx < 0:
                return math.inf
            if op_idx not in relaxed_plan:
                relaxed_plan.add(op_idx)
                for pre_fact in self.rt.ops[op_idx].pre:
                    if pre_fact not in state:
                        queue.append(pre_fact)
        return float(sum(self.rt.ops[i].cost for i in relaxed_plan))

jupyddl/heuristics/lmcut.py:
"""The LM-cut heuristic (Helmert & Domshlak, 2009).

LM-cut repeatedly computes h_max, finds a *landmark cut* of operators separating
the initial state from the goal in the justification graph, adds the cut's
cheapest operator cost to the estimate, and discounts the cut operators. It is
one of the strongest admissible heuristics for optimal planning.
"""

from __future__ import annotations

import heapq
import math
from dataclasses import dataclass

from .base import Heuristic


@dataclass
class _AugOp:
    idx: int
    pre: frozenset
    add: frozenset
    base_cost: int


class LMCutHeuristic(Heuristic):
    name = "lmcut"
    admissible = True

    def __init__(self, task):
        super().__init__(task)
        nf = task.num_facts
        self.INIT = nf  # artificial "always true" fact
        self.GOAL = nf + 1  # artificial goal fact
        self.num = nf + 2

        self.ops: list[_AugOp] = []
        for pre, add, cost in task.relaxed_operators():
            # Every operator must have at least one precondition for the
            # justification graph; use the artificial INIT fact if needed.
            pre = pre if pre else frozenset({self.INIT})
            self.ops.append(_AugOp(len(self.ops), pre, add, cost))
        # Artificial goal operator (cost 0) collecting the real goal.
        self.goal_op = len(self.ops)
        self.ops.append(_AugOp(self.goal_op, task.goals, frozenset({self.GOAL}), 0))

        self.consumers: list[list[int]] = [[] for _ in range(self.num)]
        for op in self.ops:
            for f in op.pre:
                self.consumers[f].append(op.idx)

    def __call__(self, state) -> float:
        base = set(state)
        base.add(self.INIT)
        source = frozenset(base)
        costs = [op.base_cost for op in self.ops]
        total = 0.0

        while True:
            hmax, pcf = self._hmax(source, costs)
            if hmax[self.GOAL] == 0:
                return total
            if math.isinf(hmax[self.GOAL]):
                return math.inf

            goal_zone = self._goal_zone(costs, pcf)
            cut = self._cut(source, goal_zone, pcf, hmax)
            if not cut:  # safety; should not happen when hmax(goal) > 0
                return math.inf
            min_cost = min(costs[oi] for oi in cut)
            total += min_cost
            for oi in cut:
                costs[oi] -= min_cost

    def _hmax(self, source, costs):
        inf = math.inf
        cost = [inf] * self.num
        pcf = [-1] * len(self.ops)
        counter = [len(op.pre) for op in self.ops]
        pq: list = []
        for f in source:
            cost[f] = 0
            heapq.heappush(pq, (0, f))

        def relax(op: _AugOp):
            supporter = max(op.pre, key=lambda p: cost[p])
            value = cost[supporter] + costs[op.idx]
            pcf[op.idx] = supporter
            if math.isinf(cost[supporter]):
                return
            for f in op.add:
                if value < cost[f]:
                    cost[f] = value
                    heapq.heappush(pq, (value, f))

        for op in self.ops:
            if counter[op.idx] == 0:
                relax(op)
        while pq:
            c, f = heapq.heappop(pq)
            if c > cost[f]:
                continue
            for op_idx in self.consumers[f]:
                counter[op_idx] -= 1
                if counter[op_idx] == 0:
                    relax(self.ops[op_idx])
        return cost, pcf

    def _goal_zone(self, costs, pcf):
        """Facts that reach the goal through zero-cost justification edges."""
        zone = {self.GOAL}
        changed = True
        while changed:
            changed = False
            for op in self.ops:
                supporter = pcf[op.idx]
                if (
                    costs[op.idx] == 0
                    and supporter >= 0
                    and supporter not in zone
                    and (op.add & zone)
                ):
                    zone.add(supporter)
                    changed = True
        return zone

    def _cut(self, source, goal_zone, pcf, hmax):
        """Operators crossing from the init-reachable region into the goal zone."""
        # Forward-reachable facts from the initial state that stay out of the
        # goal zone (the "before" region).
        before = {f for f in source if f not in goal_zone}
        changed = True
        while changed:
            changed = False
            for op in self.ops:
                supporter = pcf[op.idx]
                if supporter in before and not math.isinf(hmax[supporter]):
                    for f in op.add:
                        if f not in goal_zone and f not in before:
                            before.add(f)
                            changed = True
        cut = [
            op.idx for op in self.ops if pcf[op.idx] in before and (op.add & goal_zone)
        ]
        return cut

jupyddl/heuristics/relaxation.py:
"""Delete-relaxation machinery shared by h_max, h_add, h_FF and LM-cut."""

from __future__ import annotations

import heapq
import math
from dataclasses import dataclass


@dataclass
class RelaxedOp:
    idx: int
    pre: frozenset
    add: frozenset
    cost: int


class RelaxedTask:
    """Delete-relaxed view of a task: unary-ish operators + goal.

    Conditional effects are already expanded into separate relaxed operators by
    :meth:`jupyddl.task.Task.relaxed_operators`.
    """

    def __init__(self, task):
        self.num_facts = task.num_facts
        self.goal = task.goals
        self.ops = [
            RelaxedOp(i, pre, add, cost)
            for i, (pre, add, cost) in enumerate(task.relaxed_operators())
        ]
        # Index: fact -> operators that have it as a precondition.
        self.consumers: list[list[int]] = [[] for _ in range(self.num_facts)]
        self.no_pre: list[int] = []
        for op in self.ops:
            if op.pre:
                for f in op.pre:
                    self.consumers[f].append(op.idx)
            else:
                self.no_pre.append(op.idx)


def propagate_costs(rt: RelaxedTask, state, additive: bool):
    """Generalised Dijkstra computing h_max (``additive=False``) or h_add costs.

    Returns ``(cost, supporter)`` where ``cost[f]`` is the estimated cost to
    achieve fact ``f`` and ``supporter[f]`` is the operator index that achieved
    it (used for FF's relaxed-plan extraction).
    """
    inf = math.inf
    cost = [inf] * rt.num_facts
    supporter = [-1] * rt.num_facts
    counter = [len(op.pre) for op in rt.ops]
    pq: list = []

    for f in state:
        if cost[f] != 0:
            cost[f] = 0
            heapq.heappush(pq, (0, f))

    def op_value(op: RelaxedOp) -> float:
        if not op.pre:
            return op.cost
        pre_costs = [cost[p] for p in op.pre]
        agg = sum(pre_costs) if additive else max(pre_costs)
        return op.cost + agg

    def apply_op(op: RelaxedOp):
        value = op_value(op)
        if math.isinf(value):
            return
        for f in op.add:
            if value < cost[f]:
                cost[f] = value
                supporter[f] = op.idx
                heapq.heappush(pq, (value, f))

    for idx in rt.no_pre:
        apply_op(rt.ops[idx])

    while pq:
        c, f = heapq.heappop(pq)
        if c > cost[f]:
            continue
        for op_idx in rt.consumers[f]:
            counter[op_idx] -= 1
            if counter[op_idx] == 0:
                apply_op(rt.ops[op_idx])
    return cost, supporter


def goal_value(cost, goal, additive: bool) -> float:
    if not goal:
        return 0.0
    values = [cost[g] for g in goal]
    if any(math.isinf(v) for v in values):
        return math.inf
    return float(sum(values) if additive else max(values))

jupyddl/heuristics/simple.py:
"""Cheap non-relaxation heuristics."""

from __future__ import annotations

from ..task import facts_of
from .base import Heuristic


class BlindHeuristic(Heuristic):
    """0 in a goal state, otherwise the cheapest operator cost. Admissible."""

    name = "blind"
    admissible = True

    def __init__(self, task):
        super().__init__(task)
        costs = [op.cost for op in task.operators if op.cost > 0]
        self.min_cost = min(costs) if costs else 1

    def __call__(self, state) -> float:
        return 0.0 if self.task.goal_reached(state) else float(self.min_cost)


class GoalCountHeuristic(Heuristic):
    """Number of unsatisfied goal facts. Fast, informative, not admissible."""

    name = "goalcount"

    def __call__(self, state) -> float:
        return float(len(self.task.goals - facts_of(state)))

jupyddl/parser/ast.py:
"""Structured AST for PDDL.

Conditions are stored as a **formula tree in negation normal form**: the parser
pushes every ``not`` down to the atoms and rewrites ``imply``, so the grounder
only ever sees negation applied to a literal. Quantifiers stay in the tree
because expanding them needs the object pool, which only exists at grounding
time; the grounder then distributes the formula into DNF and emits one operator
per disjunct.

Numeric fluents and durative actions have their own small node types. See
:mod:`jupyddl.requirements` for exactly which PDDL requirement flags are
supported and how.
"""

from __future__ import annotations

from dataclasses import dataclass, field


class PDDLError(Exception):
    """Base class for all parsing / modelling errors."""


class UnsupportedFeatureError(PDDLError):
    """Raised when a PDDL construct outside the supported subset is used."""


@dataclass(frozen=True)
class Atom:
    """A (possibly lifted) predicate application, e.g. ``(on ?x ?y)``.

    ``args`` holds terms as raw strings: variables keep their leading ``?``
    while constants/objects are stored verbatim.
    """

    predicate: str
    args: tuple = ()

    def __str__(self) -> str:
        if not self.args:
            return f"({self.predicate})"
        return f"({self.predicate} {' '.join(self.args)})"


@dataclass(frozen=True)
class Literal:
    """A positive or negative atom used in preconditions and goals."""

    atom: Atom
    positive: bool = True


@dataclass(frozen=True)
class EqualityConstraint:
    """An ``(= a b)`` (or its negation) constraint over terms."""

    left: str
    right: str
    positive: bool = True


# --- numeric expressions -----------------------------------------------------


@dataclass(frozen=True)
class Number:
    """A numeric literal."""

    value: float


@dataclass(frozen=True)
class FluentRef:
    """A reference to a numeric fluent, e.g. ``(fuel ?truck)``."""

    name: str
    args: tuple = ()

    def __str__(self) -> str:
        if not self.args:
            return f"({self.name})"
        return f"({self.name} {' '.join(self.args)})"


@dataclass(frozen=True)
class Arithmetic:
    """A binary arithmetic expression (``+``, ``-``, ``*``, ``/``).

    Unary minus is parsed as ``(- 0 x)``.
    """

    op: str
    left: object
    right: object


@dataclass(frozen=True)
class Comparison:
    """A numeric comparison used in preconditions and goals."""

    op: str  # one of < <= = >= >
    left: object
    right: object


# --- condition formulas (negation normal form) -------------------------------


@dataclass(frozen=True)
class Truth:
    """The constant ``true`` — what an empty ``(and)`` parses to."""

    value: bool = True


@dataclass(frozen=True)
class And:
    parts: tuple = ()


@dataclass(frozen=True)
class Or:
    parts: tuple = ()


@dataclass(frozen=True)
class Exists:
    params: tuple = ()  # ((var, type), ...)
    body: object = None


@dataclass(frozen=True)
class Forall:
    params: tuple = ()  # ((var, type), ...)
    body: object = None


@dataclass
class Conjunct:
    """One ground DNF disjunct: a conjunction of literals and comparisons.

    Produced by the grounder, not by the parser. ``equalities`` are resolved
    during instantiation and never survive into a grounded operator.
    """

    literals: list = field(default_factory=list)
    equalities: list = field(default_factory=list)
    comparisons: list = field(default_factory=list)


# --- effects -----------------------------------------------------------------


@dataclass
class AddEffect:
    atom: Atom


@dataclass
class DelEffect:
    atom: Atom


@dataclass
class IncreaseCostEffect:
    """``(increase (total-cost) k)`` — the classical action-cost shorthand."""

    amount: float


@dataclass
class NumericEffect:
    """An assignment to a numeric fluent.

    ``op`` is one of ``assign``, ``increase``, ``decrease``, ``scale-up`` or
    ``scale-down``.
    """

    op: str
    target: FluentRef
    value: object  # an arithmetic expression


@dataclass
class ConjunctiveEffect:
    parts: list = field(default_factory=list)


@dataclass
class ForallEffect:
    params: list  # [(variable, type), ...]
    body: object


@dataclass
class WhenEffect:
    condition: object  # a condition formula
    body: object


# --- domain / problem --------------------------------------------------------


@dataclass
class Predicate:
    name: str
    params: list  # [(variable, type), ...]


@dataclass
class Function:
    """A declared numeric function (``:functions``)."""

    name: str
    params: list = field(default_factory=list)


@dataclass
class Action:
    name: str
    parameters: list  # [(variable, type), ...]
    precondition: object  # a condition formula
    effect: object  # one of the *Effect nodes above
    # Set when the action came from a (:durative-action ...) block; the value is
    # its duration, and the compilation is documented in jupyddl.requirements.
    duration: object = None


@dataclass
class DerivedPredicate:
    """A ``(:derived (head ?x) body)`` axiom."""

    head: Atom
    params: list  # [(variable, type), ...]
    body: object  # a condition formula


@dataclass
class Domain:
    name: str
    requirements: list
    types: dict  # child type -> parent type ("object" if none)
    constants: list  # [(name, type), ...]
    predicates: list
    actions: list
    functions: list = field(default_factory=list)
    derived: list = field(default_factory=list)
    object_fluents: list = field(default_factory=list)
    constraints: list = field(default_factory=list)

    @property
    def has_durative_actions(self) -> bool:
        return any(action.duration is not None for action in self.actions)


@dataclass
class Problem:
    name: str
    domain_name: str
    objects: list  # [(name, type), ...]
    init: list  # [Atom, ...]
    goal: object  # a condition formula
    metric_minimize_cost: bool = False
    init_numeric: dict = field(default_factory=dict)  # FluentRef -> float
    metric: object = None  # (direction, expression) or None
    preferences: list = field(default_factory=list)  # [Preference, ...]
    constraints: list = field(default_factory=list)  # [Constraint | Preference]
    timed_initials: list = field(default_factory=list)  # [TimedInitial, ...]
    init_objects: dict = field(default_factory=dict)  # object-fluent assignments
    violation_weights: dict = field(default_factory=dict)  # preference -> weight


# --- PDDL 3: preferences and trajectory constraints --------------------------


@dataclass(frozen=True)
class Preference:
    """A named soft goal or soft constraint.

    ``body`` is either a condition formula (a goal preference) or a
    :class:`Constraint` (a soft trajectory constraint). Violating it is legal;
    the ``:metric`` says what it costs.
    """

    name: str
    body: object


@dataclass(frozen=True)
class Constraint:
    """One state-trajectory constraint from a ``(:constraints ...)`` block.

    ``kind`` is the PDDL modal operator (``always``, ``sometime``, ``at-end``,
    ``at-most-once``, ``sometime-before``, ``sometime-after``) and ``args`` holds
    its operand formulas, already in negation normal form.
    """

    kind: str
    args: tuple = ()


@dataclass(frozen=True)
class TimedInitial:
    """A ``(at <time> <literal>)`` entry in ``:init``.

    The literal becomes true (or false, when negated) once the clock reaches
    ``time``, whatever the planner is doing.
    """

    time: float
    literal: Literal


@dataclass(frozen=True)
class ObjectFluent:
    """A declared function whose value is an object rather than a number."""

    name: str
    params: list
    result_type: str

jupyddl/parser/parser.py:
"""Recursive-descent PDDL parser producing :mod:`jupyddl.parser.ast` objects.

Conditions are parsed straight into **negation normal form**: ``imply`` is
rewritten, ``not`` is pushed down through ``and``/``or``/quantifiers by De
Morgan, and what comes out only ever negates a literal. Quantifiers survive into
the AST because expanding them needs the object pool, which the grounder owns.

Which requirement flags are accepted, and what each one compiles to, is decided
by :mod:`jupyddl.requirements` — not by ad-hoc checks in here.
"""

from __future__ import annotations

from ..requirements import expand as expand_requirements
from ..requirements import lookup as lookup_requirement
from ..requirements import unsupported_reason
from .ast import (
    Action,
    Constraint,
    AddEffect,
    And,
    Arithmetic,
    Atom,
    Comparison,
    ConjunctiveEffect,
    DelEffect,
    DerivedPredicate,
    Domain,
    EqualityConstraint,
    Exists,
    Forall,
    ForallEffect,
    Function,
    FluentRef,
    IncreaseCostEffect,
    Literal,
    Number,
    NumericEffect,
    ObjectFluent,
    Or,
    Preference,
    PDDLError,
    Predicate,
    Problem,
    TimedInitial,
    Truth,
    UnsupportedFeatureError,
    WhenEffect,
)
from .tokenizer import tokenize

COMPARISONS = {"<", "<=", "=", ">=", ">"}
ARITHMETIC = {"+", "-", "*", "/"}
ASSIGN_OPS = {"assign", "increase", "decrease", "scale-up", "scale-down"}
TOTAL_COST = "total-cost"

# Trajectory-constraint operators. The first group is compiled by
# jupyddl.compile; the second needs metric time, which the sequential model does
# not maintain, so it is refused by name rather than approximated.
CONSTRAINT_OPS = {
    "always",
    "sometime",
    "at-end",
    "at-most-once",
    "sometime-before",
    "sometime-after",
}
METRIC_TIME_OPS = {"within", "always-within", "hold-after", "hold-during"}

# Timed-condition / timed-effect markers inside a durative action.
TIME_SPECIFIERS = {"at", "over"}


def _parse_typed_list(items: list) -> list:
    """Parse ``?x ?y - type a b`` into ``[(name, type), ...]`` (default ``object``)."""
    result: list = []
    pending: list = []
    i = 0
    while i < len(items):
        tok = items[i]
        if tok == "-":
            typ = items[i + 1]
            if isinstance(typ, list):
                if typ and typ[0] == "either":
                    raise UnsupportedFeatureError(
                        "'either' types are not supported; declare a supertype instead"
                    )
                raise UnsupportedFeatureError("'either' types are not supported")
            for name in pending:
                result.append((name, typ))
            pending = []
            i += 2
        else:
            if isinstance(tok, list):
                raise PDDLError(f"Unexpected nested list in typed list: {tok}")
            pending.append(tok)
            i += 1
    result.extend((name, "object") for name in pending)
    return result


def _is_number(token) -> bool:
    if isinstance(token, list):
        return False
    try:
        float(token)
    except (TypeError, ValueError):
        return False
    return True


def _parse_expression(expr):
    """Parse a numeric expression: a literal, a fluent, or arithmetic."""
    if not isinstance(expr, list):
        if _is_number(expr):
            return Number(float(expr))
        # A bare name is a zero-arity fluent, e.g. total-cost.
        return FluentRef(expr, ())
    if not expr:
        raise PDDLError("Empty numeric expression")
    head = expr[0]
    if head in ARITHMETIC:
        if len(expr) == 2 and head == "-":  # unary minus
            return Arithmetic("-", Number(0.0), _parse_expression(expr[1]))
        if len(expr) != 3:
            raise UnsupportedFeatureError(
                f"'{head}' takes exactly two arguments in a numeric expression"
            )
        return Arithmetic(head, _parse_expression(expr[1]), _parse_expression(expr[2]))
    if _is_number(head):
        return Number(float(head))
    for arg in expr[1:]:
        if isinstance(arg, list):
            raise UnsupportedFeatureError(
                f"nested term inside a fluent reference is not supported: {expr}"
            )
    return FluentRef(head, tuple(expr[1:]))


def _parse_atom(expr) -> Atom:
    if not expr or isinstance(expr[0], list):
        raise PDDLError(f"Malformed atom: {expr}")
    for arg in expr[1:]:
        if isinstance(arg, list):
            raise UnsupportedFeatureError(
                f"nested/numeric term in atom is not supported: {expr}"
            )
    return Atom(expr[0], tuple(expr[1:]))


def _negate_comparison(comparison: Comparison) -> Comparison:
    flip = {"<": ">=", "<=": ">", ">": "<=", ">=": "<", "=": "!="}
    return Comparison(flip[comparison.op], comparison.left, comparison.right)


def parse_condition(expr, positive: bool = True):
    """Parse a condition into negation normal form.

    ``positive`` carries the sign inward, so ``(not (or a b))`` becomes
    ``(and (not a) (not b))`` without ever building an explicit ``Not`` node.
    """
    if not isinstance(expr, list):
        raise PDDLError(f"Malformed condition: {expr}")
    if not expr:  # () means "true"
        return Truth(positive)

    head = expr[0]

    if head == "and":
        parts = tuple(parse_condition(sub, positive) for sub in expr[1:])
        return And(parts) if positive else Or(parts)
    if head == "or":
        parts = tuple(parse_condition(sub, positive) for sub in expr[1:])
        return Or(parts) if positive else And(parts)
    if head == "not":
        if len(expr) != 2:
            raise PDDLError(f"'not' takes exactly one argument: {expr}")
        return parse_condition(expr[1], not positive)
    if head == "imply":
        if len(expr) != 3:
            raise PDDLError(f"'imply' takes exactly two arguments: {expr}")
        # (imply a b) == (or (not a) b)
        parts = (
            parse_condition(expr[1], not positive),
            parse_condition(expr[2], positive),
        )
        return Or(parts) if positive else And(parts)
    if head == "forall":
        params = tuple(_parse_typed_list(expr[1]))
        body = parse_condition(expr[2], positive)
        return Forall(params, body) if positive else Exists(params, body)
    if head == "exists":
        params = tuple(_parse_typed_list(expr[1]))
        body = parse_condition(expr[2], positive)
        return Exists(params, body) if positive else Forall(params, body)
    if head == "=":
        # `=` is equality between terms unless either side is numeric.
        left, right = expr[1], expr[2]
        if isinstance(left, list) or isinstance(right, list) or _is_number(left):
            comparison = Comparison(
                "=", _parse_expression(left), _parse_expression(right)
            )
            return comparison if positive else _negate_comparison(comparison)
        return EqualityConstraint(left, right, positive)
    if head in COMPARISONS:
        comparison = Comparison(
            head, _parse_expression(expr[1]), _parse_expression(expr[2])
        )
        return comparison if positive else _negate_comparison(comparison)

    return Literal(_parse_atom(expr), positive)


def parse_effect(expr):
    if not isinstance(expr, list):
        raise PDDLError(f"Malformed effect: {expr}")
    if not expr:
        return ConjunctiveEffect([])
    head = expr[0]
    if head == "and":
        return ConjunctiveEffect([parse_effect(sub) for sub in expr[1:]])
    if head == "not":
        return DelEffect(_parse_atom(expr[1]))
    if head == "forall":
        return ForallEffect(_parse_typed_list(expr[1]), parse_effect(expr[2]))
    if head == "when":
        return WhenEffect(parse_condition(expr[1]), parse_effect(expr[2]))
    if head in ASSIGN_OPS:
        target = expr[1]
        name = target[0] if isinstance(target, list) else target
        value = _parse_expression(expr[2])
        if name == TOTAL_COST and head == "increase":
            # The classical action-cost shorthand: keep it as an integer cost.
            if isinstance(value, Number):
                return IncreaseCostEffect(value.value)
            raise UnsupportedFeatureError(
                "(increase (total-cost) ...) needs a constant amount"
            )
        args = tuple(target[1:]) if isinstance(target, list) else ()
        return NumericEffect(head, FluentRef(name, args), value)
    if head in ("or", "imply", "exists"):
        raise UnsupportedFeatureError(f"'{head}' is not allowed in an effect")
    return AddEffect(_parse_atom(expr))


def _section_key(section) -> str:
    return section[0] if section and isinstance(section[0], str) else ""


def _check_requirements(requirements) -> None:
    """Refuse a domain up front rather than mis-planning it later."""
    for flag in requirements:
        if lookup_requirement(flag) is None:
            raise UnsupportedFeatureError(
                f"unknown requirement flag '{flag}'; see jupyddl.requirements "
                "for the full list of recognised flags"
            )
    for flag in expand_requirements(requirements):
        reason = unsupported_reason(flag)
        if reason:
            raise UnsupportedFeatureError(reason)


def parse_domain(tokens: list) -> Domain:
    if _section_key(tokens) != "define":
        raise PDDLError("Domain file must start with (define ...)")

    name = ""
    requirements: list = []
    types: dict = {}
    constants: list = []
    predicates: list = []
    functions: list = []
    actions: list = []
    derived: list = []
    constraints: list = []
    object_fluents: list = []

    for section in tokens[1:]:
        key = _section_key(section)
        if key == "domain":
            name = section[1]
        elif key == ":requirements":
            requirements = list(section[1:])
            _check_requirements(requirements)
        elif key == ":types":
            for child, parent in _parse_typed_list(section[1:]):
                # In a :types list, "child - parent" reads name=child, type=parent.
                types[child] = parent
        elif key == ":constants":
            constants = _parse_typed_list(section[1:])
        elif key == ":predicates":
            for pred in section[1:]:
                predicates.append(Predicate(pred[0], _parse_typed_list(pred[1:])))
        elif key == ":functions":
            numeric, objects = _parse_functions(section[1:])
            functions.extend(numeric)
            object_fluents.extend(objects)
        elif key == ":action":
            actions.append(_parse_action(section))
        elif key == ":durative-action":
            actions.append(_parse_durative_action(section))
        elif key == ":derived":
            derived.append(_parse_derived(section))
        elif key == ":constraints":
            constraints.extend(_parse_constraints(section[1]))
    return Domain(
        name,
        requirements,
        types,
        constants,
        predicates,
        actions,
        functions,
        derived,
        object_fluents,
        constraints,
    )


def _parse_functions(items):
    """Split a ``:functions`` block into numeric functions and object fluents.

    A trailing ``- <type>`` applies to the functions declared before it. The
    type ``number`` (or no type at all) means a numeric fluent; anything else
    means the function returns an *object*, which is compiled away by
    :mod:`jupyddl.compile`.

    Returns ``(numeric, object_fluents)``.
    """
    numeric: list = []
    object_fluents: list = []
    pending: list = []
    index = 0
    while index < len(items):
        entry = items[index]
        if entry == "-":
            result_type = items[index + 1]
            index += 2
            for name, params in pending:
                if result_type == "number":
                    numeric.append(Function(name, params))
                else:
                    object_fluents.append(ObjectFluent(name, params, result_type))
            pending = []
            continue
        if isinstance(entry, list) and entry:
            pending.append((entry[0], _parse_typed_list(entry[1:])))
        index += 1
    # Anything left untyped defaults to a number, as PDDL specifies.
    numeric.extend(Function(name, params) for name, params in pending)
    return numeric, object_fluents


def _parse_action(section: list) -> Action:
    name = section[1]
    parameters: list = []
    precondition = Truth(True)
    effect = ConjunctiveEffect([])
    i = 2
    while i < len(section):
        tag = section[i]
        val = section[i + 1]
        if tag == ":parameters":
            parameters = _parse_typed_list(val)
        elif tag == ":precondition":
            precondition = parse_condition(val)
        elif tag == ":effect":
            effect = parse_effect(val)
        i += 2
    return Action(name, parameters, precondition, effect)


def _strip_time_specifier(expr):
    """Unwrap ``(at start X)`` / ``(at end X)`` / ``(over all X)`` to ``X``.

    The sequential compilation collapses the timeline, so the marker is dropped
    once it has been validated. See :mod:`jupyddl.requirements` for what that
    costs you.
    """
    if isinstance(expr, list) and len(expr) == 3 and expr[0] in TIME_SPECIFIERS:
        marker = expr[1]
        if expr[0] == "at" and marker in ("start", "end"):
            return expr[2]
        if expr[0] == "over" and marker == "all":
            return expr[2]
    return expr


def _flatten_timed(expr, out) -> None:
    if not isinstance(expr, list) or not expr:
        return
    if expr[0] == "and":
        for sub in expr[1:]:
            _flatten_timed(sub, out)
        return
    out.append(_strip_time_specifier(expr))


def _parse_durative_action(section: list) -> Action:
    """Compile ``(:durative-action ...)`` into a single sequential action."""
    name = section[1]
    parameters: list = []
    duration = None
    condition_parts: list = []
    effect_parts: list = []

    i = 2
    while i < len(section):
        tag = section[i]
        val = section[i + 1]
        if tag == ":parameters":
            parameters = _parse_typed_list(val)
        elif tag == ":duration":
            duration = _parse_duration(val, name)
        elif tag == ":condition":
            _flatten_timed(val, condition_parts)
        elif tag == ":effect":
            _flatten_timed(val, effect_parts)
        i += 2

    if duration is None:
        raise PDDLError(f"durative action '{name}' has no :duration")

    precondition = parse_condition(["and"] + condition_parts)
    effect = parse_effect(["and"] + effect_parts)
    return Action(name, parameters, precondition, effect, duration=duration)


def _parse_duration(expr, action_name: str):
    """Read a ``:duration``, which may be an equality or a set of bounds.

    ``(= ?duration 5)`` fixes it. ``(and (>= ?duration 2) (<= ?duration 6))``
    bounds it, and the sequential compilation then picks the **shortest feasible
    duration**: with no concurrency and no continuous change, nothing in the
    model prefers a longer action, so the tightest lower bound is the
    makespan-optimal choice. Strict inequalities are refused because they have
    no shortest feasible value.
    """
    lower, upper, exact = _duration_bounds(expr, action_name)

    if exact is not None:
        if lower is not None and exact < lower:
            raise PDDLError(f"duration bounds for '{action_name}' are contradictory")
        if upper is not None and exact > upper:
            raise PDDLError(f"duration bounds for '{action_name}' are contradictory")
        return Number(exact)

    chosen = lower if lower is not None else 0.0
    if upper is not None and chosen > upper:
        raise PDDLError(
            f"duration bounds for '{action_name}' are contradictory: "
            f"the lower bound {chosen:g} exceeds the upper bound {upper:g}"
        )
    if lower is None and upper is None:
        raise PDDLError(f"malformed :duration for '{action_name}'")
    return Number(chosen)


def _duration_bounds(expr, action_name: str):
    """Collect ``(lower, upper, exact)`` from a duration constraint tree."""
    lower = upper = exact = None

    def visit(node):
        nonlocal lower, upper, exact
        if not isinstance(node, list) or not node:
            raise PDDLError(f"malformed :duration for '{action_name}'")
        head = node[0]
        if head == "and":
            for sub in node[1:]:
                visit(sub)
            return
        if head in ("<", ">"):
            raise UnsupportedFeatureError(
                f"strict duration inequality '{head}' in '{action_name}' is not "
                "supported: it has no shortest feasible duration. Use >= or <=."
            )
        if head not in ("=", ">=", "<="):
            raise PDDLError(
                f"unexpected operator '{head}' in the :duration of '{action_name}'"
            )
        if len(node) != 3 or node[1] != "?duration":
            raise UnsupportedFeatureError(
                f"the :duration of '{action_name}' must constrain ?duration "
                "against a constant"
            )
        value = _parse_expression(node[2])
        if not isinstance(value, Number):
            raise UnsupportedFeatureError(
                f"the duration of '{action_name}' must be a constant; durations "
                "that read numeric fluents are not supported"
            )
        amount = float(value.value)
        if head == "=":
            exact = amount
        elif head == ">=":
            lower = amount if lower is None else max(lower, amount)
        else:
            upper = amount if upper is None else min(upper, amount)

    visit(expr)
    return lower, upper, exact


def _parse_derived(section: list) -> DerivedPredicate:
    """Parse ``(:derived (head ?x - t) body)``."""
    head_expr = section[1]
    if not isinstance(head_expr, list) or not head_expr:
        raise PDDLError("malformed (:derived ...) head")
    params = _parse_typed_list(head_expr[1:])
    head = Atom(head_expr[0], tuple(var for var, _ in params))
    body = parse_condition(section[2])
    return DerivedPredicate(head, params, body)


def _parse_constraints(expr) -> list:
    """Parse a ``(:constraints ...)`` body into :class:`Constraint` nodes."""
    out: list = []

    def visit(node):
        if not isinstance(node, list) or not node:
            return
        head = node[0]
        if head == "and":
            for sub in node[1:]:
                visit(sub)
            return
        if head == "forall":
            # A quantified constraint expands once the object pool exists; the
            # body is what carries the modality, so recurse into it and let the
            # grounder expand the quantifier inside each operand.
            params = tuple(_parse_typed_list(node[1]))
            for constraint in _parse_constraints(node[2]):
                out.append(
                    Constraint(
                        constraint.kind,
                        tuple(Forall(params, arg) for arg in constraint.args),
                    )
                )
            return
        if head == "preference":
            name = node[1]
            for constraint in _parse_constraints(node[2]):
                out.append(Preference(name, constraint))
            return
        if head in METRIC_TIME_OPS:
            raise UnsupportedFeatureError(
                f"the '{head}' constraint needs metric time, which the "
                "sequential compilation does not maintain"
            )
        if head not in CONSTRAINT_OPS:
            raise UnsupportedFeatureError(
                f"'{head}' is not a recognised trajectory constraint; "
                f"supported: {', '.join(sorted(CONSTRAINT_OPS))}"
            )
        arity = 2 if head in ("sometime-before", "sometime-after") else 1
        operands = node[1 : 1 + arity]
        if len(operands) != arity:
            raise PDDLError(f"'{head}' takes {arity} operand(s): {node}")
        out.append(Constraint(head, tuple(parse_condition(o) for o in operands)))

    visit(expr)
    return out


def _split_preferences(expr, found: list):
    """Strip ``(preference name phi)`` out of a goal, leaving the hard part.

    Returns the goal s-expression with every preference replaced by ``()``
    (trivially true) and appends the extracted ones to ``found``.
    """
    if not isinstance(expr, list) or not expr:
        return expr
    head = expr[0]
    if head == "preference":
        if len(expr) == 3:
            found.append((expr[1], expr[2]))
        elif len(expr) == 2:  # an unnamed preference
            found.append((f"__pref{len(found) + 1}", expr[1]))
        else:
            raise PDDLError(f"malformed preference: {expr}")
        return []
    if head in ("and", "or", "not", "imply"):
        return [head] + [_split_preferences(sub, found) for sub in expr[1:]]
    if head in ("forall", "exists"):
        return [head, expr[1], _split_preferences(expr[2], found)]
    return expr


def _parse_timed_initial(fact):
    """Parse ``(at <time> <literal>)`` from ``:init``; None when it is an atom.

    ``(at 5 (on a b))`` is a timed initial literal, but ``(at truck1 depot)`` is
    an ordinary atom about location -- the number in the second position is what
    distinguishes them.
    """
    if len(fact) != 3 or fact[0] != "at" or not _is_number(fact[1]):
        return None
    body = fact[2]
    if not isinstance(body, list) or not body:
        raise PDDLError(f"malformed timed initial literal: {fact}")
    if body[0] == "not":
        return TimedInitial(float(fact[1]), Literal(_parse_atom(body[1]), False))
    return TimedInitial(float(fact[1]), Literal(_parse_atom(body), True))


def _collect_violation_weights(expression, weights: dict, factor: float = 1.0):
    """Read the ``(is-violated p)`` coefficients out of a metric expression.

    ``(+ (total-cost) (* 4 (is-violated p)))`` prices preference ``p`` at 4.
    Anything not of that shape is ignored; the default weight is 1.
    """
    if isinstance(expression, FluentRef):
        if expression.name == "is-violated" and expression.args:
            name = expression.args[0]
            weights[name] = weights.get(name, 0.0) + factor
        return
    if isinstance(expression, Arithmetic):
        if expression.op == "+":
            _collect_violation_weights(expression.left, weights, factor)
            _collect_violation_weights(expression.right, weights, factor)
        elif expression.op == "-":
            _collect_violation_weights(expression.left, weights, factor)
            _collect_violation_weights(expression.right, weights, -factor)
        elif expression.op == "*":
            left, right = expression.left, expression.right
            if isinstance(left, Number):
                _collect_violation_weights(right, weights, factor * left.value)
            elif isinstance(right, Number):
                _collect_violation_weights(left, weights, factor * right.value)


def parse_problem(tokens: list) -> Problem:
    if _section_key(tokens) != "define":
        raise PDDLError("Problem file must start with (define ...)")

    name = ""
    domain_name = ""
    objects: list = []
    init: list = []
    init_numeric: dict = {}
    goal = Truth(True)
    metric = None
    metric_minimize_cost = False
    preferences: list = []
    constraints: list = []
    timed_initials: list = []
    init_objects: dict = {}
    violation_weights: dict = {}

    for section in tokens[1:]:
        key = _section_key(section)
        if key == "problem":
            name = section[1]
        elif key == ":domain":
            domain_name = section[1]
        elif key == ":objects":
            objects = _parse_typed_list(section[1:])
        elif key == ":requirements":
            _check_requirements(list(section[1:]))
        elif key == ":init":
            for fact in section[1:]:
                if not fact:
                    continue
                if fact[0] == "=":
                    target, value = fact[1], fact[2]
                    fluent = _parse_expression(target)
                    if not isinstance(fluent, FluentRef):
                        continue
                    if _is_number(value):
                        init_numeric[fluent] = float(value)
                    elif not isinstance(value, list):
                        # `(= (location p1) depot)` assigns an object, not a
                        # number: an object fluent, compiled away later.
                        init_objects[fluent] = value
                    continue
                timed = _parse_timed_initial(fact)
                if timed is not None:
                    timed_initials.append(timed)
                    continue
                init.append(_parse_atom(fact))
        elif key == ":goal":
            stripped = _split_preferences(section[1], preferences)
            goal = parse_condition(stripped)
        elif key == ":metric":
            metric, metric_minimize_cost = _parse_metric(section)
            if metric is not None:
                _collect_violation_weights(metric[1], violation_weights)
        elif key == ":constraints":
            constraints.extend(_parse_constraints(section[1]))
    return Problem(
        name,
        domain_name,
        objects,
        init,
        goal,
        metric_minimize_cost,
        init_numeric,
        metric,
        [
            Preference(pref_name, parse_condition(body))
            for pref_name, body in preferences
        ],
        constraints,
        timed_initials,
        init_objects,
        violation_weights,
    )


def _parse_metric(section):
    """Read ``(:metric minimize <expr>)``; returns ``((dir, expr), is_total_cost)``."""
    if len(section) < 3:
        return None, False
    direction = section[1]
    if direction not in ("minimize", "maximize"):
        raise PDDLError(f"unknown metric direction '{direction}'")
    expression = _parse_expression(section[2])
    is_total_cost = (
        isinstance(expression, FluentRef)
        and expression.name == TOTAL_COST
        and direction == "minimize"
    )
    return (direction, expression), is_total_cost


def parse(text: str):
    """Parse PDDL text into a :class:`Domain` or :class:`Problem`."""
    tokens = tokenize(text)
    for section in tokens[1:]:
        key = _section_key(section)
        if key == "domain":
            return parse_domain(tokens)
        if key == "problem":
            return parse_problem(tokens)
    raise PDDLError("Could not determine whether input is a domain or a problem")


def parse_domain_file(path: str) -> Domain:
    with open(path, "r", encoding="utf-8") as handle:
        return parse_domain(tokenize(handle.read()))


def parse_problem_file(path: str) -> Problem:
    with open(path, "r", encoding="utf-8") as handle:
        return parse_problem(tokenize(handle.read()))

jupyddl/search/best_first_planners.py:
"""Best-first planners defined by their priority function over ``(g, h)``."""

from __future__ import annotations

from .base import Planner, best_first, heuristic_name
from .result import SearchResult


class UniformCostSearch(Planner):
    """Dijkstra's algorithm: priority = g. Cost-optimal, uninformed."""

    name = "dijkstra"
    optimal = True

    def search(self, task, heuristic=None, observer=None, budget=None) -> SearchResult:
        if observer is not None:
            observer.on_start(task, self.name, "")
        return best_first(
            task, lambda g, h: g, heuristic=None, observer=observer, budget=budget
        )


class GreedyBestFirstSearch(Planner):
    """Greedy best-first: priority = h. Fast but not optimal."""

    name = "gbfs"
    requires_heuristic = True

    def search(self, task, heuristic=None, observer=None, budget=None) -> SearchResult:
        if observer is not None:
            observer.on_start(task, self.name, heuristic_name(heuristic))
        return best_first(
            task, lambda g, h: h, heuristic=heuristic, observer=observer, budget=budget
        )


class AStarSearch(Planner):
    """A*: priority = g + h. Cost-optimal with an admissible heuristic."""

    name = "astar"
    requires_heuristic = True
    optimal = True

    def search(self, task, heuristic=None, observer=None, budget=None) -> SearchResult:
        if observer is not None:
            observer.on_start(task, self.name, heuristic_name(heuristic))
        return best_first(
            task,
            lambda g, h: g + h,
            heuristic=heuristic,
            observer=observer,
            budget=budget,
        )


class WeightedAStarSearch(Planner):
    """Weighted A*: priority = g + w * h. Bounded-suboptimal for w > 1."""

    name = "wastar"
    requires_heuristic = True

    def __init__(self, weight: float = 2.0):
        self.weight = weight

    def search(self, task, heuristic=None, observer=None, budget=None) -> SearchResult:
        w = self.weight
        if observer is not None:
            observer.on_start(task, self.name, heuristic_name(heuristic))
        return best_first(
            task,
            lambda g, h: g + w * h,
            heuristic=heuristic,
            observer=observer,
            budget=budget,
        )

jupyddl/search/node.py:
"""Search-node helpers and plan reconstruction."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Optional


@dataclass
class SearchNode:
    state: frozenset
    parent: Optional["SearchNode"]
    action: object  # Operator that produced this node (None for the root)
    g: int  # accumulated path cost
    depth: int  # number of actions from the root


def make_root(state: frozenset) -> SearchNode:
    return SearchNode(state, None, None, 0, 0)


def make_child(parent: SearchNode, action, state: frozenset, cost: int) -> SearchNode:
    return SearchNode(state, parent, action, parent.g + cost, parent.depth + 1)


def extract_plan(node: SearchNode) -> list:
    """Walk parent pointers to recover the ordered list of operators."""
    plan = []
    while node is not None and node.action is not None:
        plan.append(node.action)
        node = node.parent
    plan.reverse()
    return plan

jupyddl/search/result.py:
"""Search result, statistics and resource budgets shared by all planners."""

from __future__ import annotations

import time
from dataclasses import dataclass, field
from typing import Optional


@dataclass
class SearchStats:
    """Bookkeeping collected while searching (for comparative analysis)."""

    expanded: int = 0
    generated: int = 0
    evaluated: int = 0  # heuristic evaluations
    reopened: int = 0
    deadends: int = 0
    runtime: float = 0.0
    # True when the planner stopped because it ran out of budget rather than
    # because it finished. An optimality claim only holds when this is False.
    truncated: bool = False

    def as_dict(self) -> dict:
        return {
            "expanded": self.expanded,
            "generated": self.generated,
            "evaluated": self.evaluated,
            "reopened": self.reopened,
            "deadends": self.deadends,
            "runtime": self.runtime,
            "truncated": self.truncated,
        }


class Budget:
    """A cooperative resource limit checked inside a search loop.

    Python has no safe way to interrupt a running search from outside, so the
    planners poll this instead.

    ``check_every`` throttles how often the clock is read. It defaults to 1 --
    every call -- because a single expansion can cost tens of milliseconds under
    an expensive heuristic like LM-cut, and a coarser interval would overshoot a
    short time limit by orders of magnitude. Reading a monotonic clock costs
    tens of nanoseconds, which is nothing beside an expansion.

    A budget that is hit sets ``stats.truncated``, so a caller can always tell
    "no plan exists" apart from "we stopped looking".
    """

    def __init__(
        self,
        max_expansions: Optional[int] = None,
        time_limit: Optional[float] = None,
        check_every: int = 1,
    ):
        self.max_expansions = max_expansions
        self.time_limit = time_limit
        self.check_every = max(1, int(check_every))
        self._deadline = None

    @property
    def unlimited(self) -> bool:
        return self.max_expansions is None and self.time_limit is None

    def start(self) -> "Budget":
        self._deadline = (
            None if self.time_limit is None else time.perf_counter() + self.time_limit
        )
        return self

    def exceeded(self, stats: SearchStats) -> bool:
        if self.max_expansions is not None and stats.expanded >= self.max_expansions:
            stats.truncated = True
            return True
        if self._deadline is not None and stats.expanded % self.check_every == 0:
            if time.perf_counter() >= self._deadline:
                stats.truncated = True
                return True
        return False

    def __repr__(self) -> str:  # pragma: no cover - debugging aid
        return (
            f"Budget(max_expansions={self.max_expansions}, "
            f"time_limit={self.time_limit})"
        )


def make_budget(max_expansions=None, time_limit=None) -> Optional[Budget]:
    """Build a :class:`Budget`, or ``None`` when nothing is limited."""
    if max_expansions is None and time_limit is None:
        return None
    return Budget(max_expansions, time_limit).start()


@dataclass
class SearchResult:
    """The outcome of a search: a plan (list of operators) plus statistics."""

    solved: bool
    plan: Optional[list] = None  # list[Operator]
    cost: Optional[int] = None
    stats: SearchStats = field(default_factory=SearchStats)

    @property
    def plan_length(self) -> Optional[int]:
        return None if self.plan is None else len(self.plan)

    @property
    def truncated(self) -> bool:
        """The search stopped on a budget, so 'no plan' means 'none found yet'."""
        return self.stats.truncated

    def plan_names(self, canonical: bool = False) -> Optional[list]:
        """Operator names; ``canonical=True`` drops compilation tags like ``#2``."""
        if self.plan is None:
            return None
        if canonical:
            return [op.base_name for op in self.plan]
        return [op.name for op in self.plan]

jupyddl/task.py:
"""Grounded task representation.

A :class:`Task` is a fully grounded planning problem where every fact is an
integer id, so states are cheap frozensets and successor generation is set
arithmetic. Negative preconditions and goals are compiled away into *positive
normal form* by the grounder, so preconditions and goals are purely positive.
Conditional effects are retained explicitly, so ADL domains are solved rather
than rejected.

Three optional layers ride on top, each inert unless the domain uses it:

* **numeric fluents** — when present, a state is a :class:`State` carrying a
  tuple of numbers alongside the fact set instead of a bare frozenset;
* **derived predicates** — :class:`Axiom` rules closed to a fixpoint after every
  state change, so nothing downstream ever sees an unclosed state;
* **durations** — carried per operator so temporal plans can report a makespan.

A classical STRIPS task pays for none of them: the checks are single truthiness
tests on empty tuples.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Optional


@dataclass(frozen=True)
class CondEffect:
    """A conditional effect: when ``condition`` holds, apply add/delete."""

    condition: frozenset
    add: frozenset
    delete: frozenset


@dataclass(frozen=True)
class Axiom:
    """A grounded derived-predicate rule: ``body`` implies ``head``."""

    head: int
    body: frozenset


@dataclass(frozen=True)
class State:
    """A state with numeric fluents: a fact set plus a vector of numbers."""

    facts: frozenset
    values: tuple

    def __contains__(self, fact) -> bool:
        return fact in self.facts

    def __iter__(self):
        return iter(self.facts)

    def __len__(self) -> int:
        return len(self.facts)


def facts_of(state) -> frozenset:
    """The fact set of a state, whether or not it carries numbers."""
    return state.facts if isinstance(state, State) else state


def values_of(state) -> tuple:
    """The numeric vector of a state (empty for classical tasks)."""
    return state.values if isinstance(state, State) else ()


@dataclass(frozen=True)
class Operator:
    """A grounded action over integer fact ids.

    ``numeric_pre`` holds callables ``values -> bool`` and ``numeric_eff`` holds
    ``(index, values -> float)`` pairs; both are empty for classical tasks. The
    right-hand sides are all evaluated against the *pre-state*, so simultaneous
    assignments behave as PDDL specifies.
    """

    name: str
    precond: frozenset
    add: frozenset
    delete: frozenset
    cond_effects: tuple = ()
    cost: int = 1
    numeric_pre: tuple = ()
    numeric_eff: tuple = ()
    duration: float = 0.0

    @property
    def base_name(self) -> str:
        """The action as written in the domain, without any compilation tag.

        Splitting a disjunctive precondition produces ``move(a,b)#2``; a plan
        handed to another tool wants ``move(a,b)``. The tag stays on ``name`` so
        traces can still tell the disjuncts apart.
        """
        head, sep, _ = self.name.partition("#")
        return head if sep else self.name

    def applicable(self, state) -> bool:
        if not self.precond <= facts_of(state):
            return False
        if self.numeric_pre:
            values = values_of(state)
            return all(test(values) for test in self.numeric_pre)
        return True

    def apply(self, state):
        """Return the successor state (conditions evaluated in ``state``)."""
        facts = facts_of(state)
        dels = set(self.delete)
        adds = set(self.add)
        for effect in self.cond_effects:
            if effect.condition <= facts:
                dels |= effect.delete
                adds |= effect.add
        # Adds take precedence over deletes (standard STRIPS semantics).
        new_facts = frozenset((facts - dels) | adds)

        if not isinstance(state, State):
            return new_facts
        if not self.numeric_eff:
            return State(new_facts, state.values)
        values = list(state.values)
        old = state.values  # every right-hand side reads the pre-state
        for index, compute in self.numeric_eff:
            values[index] = compute(old)
        return State(new_facts, tuple(values))


@dataclass
class Task:
    """A grounded planning task."""

    name: str
    facts: tuple  # id -> human-readable fact string
    init: frozenset
    goals: frozenset
    operators: tuple
    metric_cost: bool = False
    axioms: tuple = ()
    numeric_names: tuple = ()  # id -> human-readable fluent string
    init_values: tuple = ()
    goal_numeric: tuple = ()  # callables values -> bool
    temporal: bool = False
    # Index of the elapsed-time fluent, when a timed-initial-literal
    # compilation introduced one. Waiting for a timed literal advances the clock
    # without any action taking that long, so a plan's real end time is the
    # clock, not the sum of its durations.
    clock_index: Optional[int] = None
    metric: Optional[str] = None
    requirements: tuple = ()
    # Operators introduced purely by a compilation step (a disjunctive goal,
    # say). They are real operators to the search but noise in a printed plan.
    synthetic: frozenset = field(default_factory=frozenset)

    @property
    def num_facts(self) -> int:
        return len(self.facts)

    @property
    def numeric(self) -> bool:
        return bool(self.numeric_names)

    def initial_state(self):
        """The initial state, with axioms already closed."""
        if self.numeric:
            return self.close(State(self.init, self.init_values))
        return self.close(self.init)

    def close(self, state):
        """Add every derived fact entailed by ``state`` (least fixpoint).

        Rules are re-scanned until nothing new fires. Derived predicates cannot
        appear in action effects, so this only ever grows the fact set.
        """
        if not self.axioms:
            return state
        facts = set(facts_of(state))
        changed = True
        while changed:
            changed = False
            for axiom in self.axioms:
                if axiom.head not in facts and axiom.body <= facts:
                    facts.add(axiom.head)
                    changed = True
        closed = frozenset(facts)
        if isinstance(state, State):
            return State(closed, state.values)
        return closed

    def apply(self, operator: Operator, state):
        """Apply ``operator`` to ``state`` and re-close the derived predicates."""
        return self.close(operator.apply(state))

    def goal_reached(self, state) -> bool:
        if not self.goals <= facts_of(state):
            return False
        if self.goal_numeric:
            values = values_of(state)
            return all(test(values) for test in self.goal_numeric)
        return True

    def applicable_operators(self, state):
        for operator in self.operators:
            if operator.applicable(state):
                yield operator

    def fact_name(self, fact_id: int) -> str:
        return self.facts[fact_id]

    def state_str(self, state) -> str:
        return "{" + ", ".join(sorted(self.facts[f] for f in facts_of(state))) + "}"

    def makespan(self, plan) -> float:
        """When the plan finishes, under the sequential temporal compilation.

        Normally that is the sum of the action durations. If the task has a
        clock — because timed initial literals made one necessary — the plan may
        also have *waited*, so the clock is replayed instead: idle time counts
        towards the end time even though no action was running.
        """
        plan = list(plan or ())
        if self.clock_index is None:
            return sum(op.duration for op in plan)
        state = self.initial_state()
        for operator in plan:
            state = self.apply(operator, state)
        return float(values_of(state)[self.clock_index])

    def visible_plan(self, plan) -> list:
        """Drop operators that only exist because of a compilation step."""
        if not self.synthetic:
            return list(plan or ())
        return [op for op in (plan or ()) if op.name not in self.synthetic]

    def relaxed_operators(self):
        """Delete-relaxation operator view used by relaxation heuristics.

        Every conditional effect becomes its own relaxed operator whose
        precondition is the action precondition conjoined with the effect
        condition. This is the standard, sound treatment of conditional effects
        under delete relaxation. Numeric preconditions are *ignored*, which only
        makes the relaxation more permissive and so keeps the heuristics
        admissible; axioms enter as zero-cost rules for the same reason.
        Returns a list of ``(precond, add, cost)``.
        """
        relaxed = []
        for operator in self.operators:
            if operator.add:
                relaxed.append((operator.precond, operator.add, operator.cost))
            for effect in operator.cond_effects:
                if effect.add:
                    relaxed.append(
                        (operator.precond | effect.condition, effect.add, operator.cost)
                    )
            if not operator.add and not operator.cond_effects:
                # Keep operators with only delete effects visible (no-op in the
                # relaxation) so nothing downstream assumes non-empty adds.
                relaxed.append((operator.precond, frozenset(), operator.cost))
        for axiom in self.axioms:
            relaxed.append((axiom.body, frozenset({axiom.head}), 0))
        return relaxed
